 public const string Folder="TruckPoker",Scene="Assets/TruckPoker/Scenes/TruckPoker.unity";static TMP_FontAsset font;static Material ink,cream,gold,cloth,pink,purple;static PokerMatch m;static PokerPresentation p;
 public static void Create(){if(EditorApplication.isPlaying||EditorApplication.isCompiling||EditorUtility.scriptCompilationFailed)throw new Exception("Stopped compiled Editor required");foreach(var folder in new[]{"Models","Scenes","Materials","Audio"})Directory.CreateDirectory("Assets/"+Folder+"/"+folder);m=SportsEventAuthoring.Begin<PokerMatch>(Folder);m.option=0;m.setup.count=4;m.NormalizeSetup();font=SportsBroadcastAuthoring.Theme().headingFont;p=m.gameObject.AddComponent<PokerPresentation>();p.match=m;m.presentation=p;ink=Mat("Casino midnight",new Color(.025f,.04f,.075f),.18f);cream=Mat("Warm ivory",new Color(.97f,.93f,.78f),.3f);gold=Mat("Brushed brass",new Color(.85f,.55f,.15f),.65f);gold.SetFloat("_Metallic",.7f);cloth=Mat("Deep emerald felt",new Color(.025f,.25f,.19f),.06f);pink=Mat("Dealer rose paint",new Color(.92f,.16f,.5f),.5f);purple=Mat("Dealer tailored purple blouse",new Color(.26f,.045f,.39f),.16f);Room();Participants();Dealer();Cameras();p.buttonMarker=Round("Rotating dealer button",null,new Vector3(0,2,0),new Vector3(.7f,.07f,.7f),cream,PrimitiveType.Cylinder);m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[1]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Hover.wav");m.feedback.clips[2]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Click.wav");m.feedback.clips[3]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Notification.wav");m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);BetUI();SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);Validate();}
