 static Transform Model(string name,Transform parent,Vector3 position,Vector3 scale,Mesh mesh,Material mat){var g=new GameObject(name).transform;g.SetParent(parent,false);g.localPosition=position;g.localScale=scale;g.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;g.gameObject.AddComponent<MeshRenderer>().sharedMaterial=mat;return g;}
