 static void Room(){RenderSettings.ambientLight=new Color(.28f,.24f,.31f);var contact=SportsEventAuthoring.Contact(Folder,"Casino floor",.6f,.05f);SportsEventAuthoring.Box("Carpeted casino floor",new Vector3(0,-.25f,0),new Vector3(60,.5f,52),Mat("Plum casino carpet",new Color(.13f,.035f,.11f),.06f),contact);var table=new GameObject("Installed restaurant table base").transform;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(table,"Assets/Modern Resaturant - building and interior/Models/Prefabs/Restaurant_Table_Rectangular_1.prefab",new Vector3(15,1.4f,9),0,false,Folder);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckSumo/Models/Beveled continuous ring.asset");if(mesh==null)throw new Exception("Existing modeled round platform missing");Model("Modeled oval brass table rim",null,new Vector3(0,1.48f,0),new Vector3(9.3f,.35f,6.4f),mesh,gold);Model("Raised continuous oval playing felt",null,new Vector3(0,1.51f,0),new Vector3(9,.08f,6.1f),mesh,cloth);for(int side=-1;side<=1;side+=2){SportsEventAuthoring.Box("Casino architectural wall",new Vector3(side*25,4,0),new Vector3(.5f,8,45),ink);for(int z=0;z<5;z++){var light=new GameObject("Warm casino wall light").AddComponent<Light>();light.transform.position=new Vector3(side*22,5,-16+z*8);light.type=LightType.Point;light.color=new Color(1,.67f,.32f);light.range=14;light.intensity=7;light.shadows=LightShadows.None;Round("Brass wall-light fixture",null,light.transform.position,new Vector3(.2f,1,.4f),gold);}}var title=WorldText("TRUCK POKER",new Vector3(0,6.5f,13),.28f,new Color(1,.7f,.2f));title.transform.rotation=Quaternion.identity;WorldText("OFFLINE · VIRTUAL CHIPS ONLY",new Vector3(0,5.1f,13),.12f,Color.white).transform.rotation=Quaternion.identity;
 p.board=new PokerCardView[5];for(int c=0;c<5;c++)p.board[c]=WorldCard("Public community card "+c,new Vector3((c-2)*1.24f,1.54f,.1f),0);Round("Render-only public deck of card backs",null,new Vector3(3.9f,1.6f,2.5f),new Vector3(.8f,.14f,1.15f),ink,PrimitiveType.Cube);}
 static TMP_Text WorldText(string text,Vector3 position,float height,Color color){var g=new GameObject(text);g.transform.position=position;var label=g.AddComponent<TextMeshPro>();label.font=font;label.text=text;label.fontSize=30;label.enableAutoSizing=false;label.alignment=TextAlignmentOptions.Center;label.rectTransform.sizeDelta=new Vector2(12,2);label.color=color;label.transform.localScale=Vector3.one*height;return label;}
 static void Participants(){m.avatars=new Transform[8];p.names=new TMP_Text[8];p.stacks=new TMP_Text[8];p.chips=new Transform[8];p.expressions=new Transform[8];p.seatCards=new PokerCardView[16];for(int i=0;i<8;i++){float angle=(42+i*276f/7)*Mathf.Deg2Rad;var avatar=new GameObject("Seated truck participant "+(i+1)).transform;avatar.position=new Vector3(Mathf.Sin(angle)*12,1.6f,Mathf.Cos(angle)*9);avatar.rotation=Quaternion.LookRotation(new Vector3(-avatar.position.x,0,-avatar.position.z));m.avatars[i]=avatar;var expression=new GameObject("Public truck gesture "+i).transform;expression.SetParent(avatar,false);p.expressions[i]=expression;var model=LWS.TruckHockey.Editor.HockeyAuthoring.TruckGeometry(expression,3);var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",m.setup.players[i].color);block.SetColor("_Color",m.setup.players[i].color);foreach(var r in model.GetComponentsInChildren<Renderer>())if(r.name=="Cab")r.SetPropertyBlock(block);Layer(avatar,10+i);var chair=new GameObject("Installed padded participant chair "+i).transform;chair.position=avatar.position+Vector3.down*1.5f-avatar.forward*.5f;chair.rotation=avatar.rotation;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(chair,"Assets/Modern Resaturant - building and interior/Models/Prefabs/Restaurant_chair.prefab",new Vector3(3,2.3f,3),0,false,Folder);p.names[i]=WorldText(m.setup.players[i].name,avatar.position+Vector3.up*2.4f,.18f,m.setup.players[i].color);p.names[i].gameObject.AddComponent<SportsPerCameraBillboard>();p.stacks[i]=WorldText("1000 CHIPS",new Vector3(Mathf.Sin(angle)*7.4f,1.65f,Mathf.Cos(angle)*4.9f),.11f,Color.white);p.stacks[i].transform.rotation=Quaternion.Euler(90,0,-angle*Mathf.Rad2Deg);var stack=new GameObject("Public chip stack "+i).transform;stack.position=new Vector3(Mathf.Sin(angle)*7.6f,1.55f,Mathf.Cos(angle)*5.1f);p.chips[i]=stack;for(int n=0;n<6;n++){var chip=Round("Ridged virtual casino chip",stack,new Vector3(0,n*.045f,0),new Vector3(.55f,.025f,.55f),n%2==0?cream:gold,PrimitiveType.Cylinder);for(int stripe=0;stripe<6;stripe++){float a=stripe*Mathf.PI/3;Round("Chip edge enamel marker",chip,new Vector3(Mathf.Sin(a)*.45f,.6f,Mathf.Cos(a)*.45f),new Vector3(.1f,.05f,.1f),ink);}}for(int c=0;c<2;c++){var pos=new Vector3(Mathf.Sin(angle)*6.4f,1.55f,Mathf.Cos(angle)*4.4f)+avatar.right*(c==0?-.45f:.45f);p.seatCards[i*2+c]=WorldCard("Unrevealed seat card "+i+" "+c,pos,-angle*Mathf.Rad2Deg);}}}
 static void Dealer(){var root=new GameObject("Adult anthropomorphic truck dealer · tailored casino uniform").transform;root.position=new Vector3(0,.2f,9.5f);root.rotation=Quaternion.Euler(0,180,0);p.dealer=root;var visual=LWS.TruckHockey.Editor.HockeyAuthoring.TruckGeometry(root,3.8f);foreach(var r in visual.GetComponentsInChildren<Renderer>())if(r.name=="Cab")r.sharedMaterial=pink;Round("Tailored blouse body",root,new Vector3(0,.65f,.65f),new Vector3(1.5f,1.35f,.85f),purple);for(int side=-1;side<=1;side+=2){Round("Fully clothed cartoon blouse curve",root,new Vector3(side*.37f,.95f,1.04f),new Vector3(.9f,.84f,.72f),purple);Round("White fabric collar",root,new Vector3(side*.25f,1.42f,.91f),new Vector3(.56f,.15f,.4f),cream);var eye=Round("Friendly dealer windshield eye",root,new Vector3(side*.27f,1.62f,.74f),new Vector3(.38f,.29f,.10f),cream);Round("Dealer iris",eye,new Vector3(0,0,.5f),new Vector3(.42f,.65f,.18f),Mat("Dealer bright iris",new Color(.08f,.45f,.72f),.6f));Round("Dealer pupil",eye,new Vector3(0,0,.63f),new Vector3(.2f,.43f,.12f),ink);}var arm=new GameObject("Public animated dealing glove").transform;arm.SetParent(root,false);arm.localPosition=new Vector3(.8f,.9f,1);Round("Dealer satin sleeve",arm,new Vector3(0,0,.25f),new Vector3(.28f,.28f,.8f),purple,PrimitiveType.Capsule);Round("Dealer cloth glove",arm,new Vector3(0,0,.7f),new Vector3(.38f,.17f,.4f),cream);p.dealHand=arm;Hair(root);}
 static void Hair(Transform dealer){const string path="Assets/TruckPoker/Art/DealerHair/Hair_Ponytail_01.fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);if(importer==null)throw new Exception("Owned Ponytail01 import missing");if(!importer.isReadable){importer.isReadable=true;importer.SaveAndReimport();}var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);var hair=UnityEngine.Object.Instantiate(source,dealer,false);hair.name="Owned blonde ponytail with Unity Cloth";var skins=hair.GetComponentsInChildren<SkinnedMeshRenderer>(true);var skin=skins.First(r=>r.sharedMesh.vertexCount==skins.Min(s=>s.sharedMesh.vertexCount));foreach(var lod in hair.GetComponentsInChildren<LODGroup>())lod.enabled=false;foreach(var r in skins)r.enabled=r==skin;var blonde=Mat("Dealer golden blonde hair",new Color(.96f,.69f,.2f),.22f);blonde.SetFloat("_Cull",0);blonde.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/TruckPoker/Art/DealerHair/T_Ponytail_01_AO.tga"));skin.sharedMaterials=Enumerable.Repeat(blonde,skin.sharedMaterials.Length).ToArray();var bounds=skin.bounds;float scale=.95f/Mathf.Max(.01f,bounds.size.y);hair.transform.localScale*=scale;bounds=skin.bounds;hair.transform.position+=dealer.TransformPoint(new Vector3(0,1.95f,-.18f))-bounds.center;skin.updateWhenOffscreen=true;var simulation=skin.gameObject.AddComponent<Cloth>();simulation.useGravity=true;simulation.damping=.65f;simulation.bendingStiffness=.65f;simulation.stretchingStiffness=.95f;simulation.clothSolverFrequency=60;simulation.externalAcceleration=new Vector3(.15f,0,.08f);var vertices=skin.sharedMesh.vertices;var coefficients=new ClothSkinningCoefficient[vertices.Length];float top=skin.sharedMesh.bounds.max.z;for(int i=0;i<vertices.Length;i++)coefficients[i]=new ClothSkinningCoefficient{maxDistance=vertices[i].z>top-.07f?0:.055f,collisionSphereDistance=0};simulation.coefficients=coefficients;}
 static void Cameras(){m.broadcast=SportsEventAuthoring.Camera("Poker public table broadcast");m.broadcast.view.cullingMask=~(15<<25);m.broadcast.Pose(new Vector3(0,1.5f,0),new Vector3(0,14,-17),58,true);m.seats=new SportsEventCamera[4];m.cabAnchors=new Transform[4];m.looks=new SportsCabLook[4];for(int i=0;i<4;i++){var camera=SportsEventAuthoring.Camera("Independent seated driver view "+i);camera.view.enabled=false;camera.view.fieldOfView=75;camera.view.farClipPlane=150;SportsChaosAuthoring.Cab(camera.view,Folder,i,25);var interior=camera.transform.Find("Driver seat interior");var anchor=new GameObject("Stable cockpit anchor "+i).transform;interior.SetParent(anchor,false);m.cabAnchors[i]=anchor;m.looks[i]=camera.gameObject.AddComponent<SportsCabLook>();m.seats[i]=camera;}m.cameras=new[]{m.broadcast.view};}
 static RectTransform Rect(string name,Transform parent,Vector2 size,Vector2 position,Vector2 anchor,Vector2 pivot){var r=SportsUIAuthoring.Rect(name,parent,size,position).GetComponent<RectTransform>();r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;return r;}
