 static PokerCardView Card(string name,Transform parent,Vector2 size){var root=SportsUIAuthoring.Rect(name,parent,size,Vector2.zero);var card=root.AddComponent<PokerCardView>();var face=SportsUIAuthoring.Rect("Ivory card face",root.transform,size,Vector2.zero);face.AddComponent<Image>().color=new Color(.98f,.95f,.86f);var plate=face.AddComponent<SportsBroadcastPlate>();plate.cut=6;plate.accent=false;card.face=face;card.rank=Text("Rank",face.transform,"",new Vector2(size.x*.65f,size.y*.35f),new Vector2(-size.x*.13f,size.y*.27f),Mathf.RoundToInt(size.y*.3f));card.corner=Text("Opposite rank",face.transform,"",new Vector2(size.x*.3f,size.y*.23f),new Vector2(size.x*.25f,-size.y*.33f),Mathf.RoundToInt(size.y*.18f));card.corner.transform.localRotation=Quaternion.Euler(0,0,180);var mark=SportsUIAuthoring.Rect("Vector suit",face.transform,new Vector2(size.x*.65f,size.y*.43f),new Vector2(0,-size.y*.04f));card.suit=mark.AddComponent<PokerSuitGraphic>();card.suit.raycastTarget=false;var back=SportsUIAuthoring.Rect("Original industrial card back",root.transform,size,Vector2.zero);back.AddComponent<Image>().color=SportsBroadcastCanvas.Ink;var bevel=back.AddComponent<SportsBroadcastPlate>();bevel.cut=6;bevel.accent=true;var logo=Text("Card back monogram",back.transform,"TS",new Vector2(size.x*.8f,size.y*.6f),Vector2.zero,Mathf.RoundToInt(size.y*.24f));logo.color=SportsBroadcastCanvas.Orange;card.back=back;card.Clear(false);return card;}
 static PokerCardView WorldCard(string name,Vector3 position,float yaw){var holder=new GameObject(name).transform;holder.position=position;holder.rotation=Quaternion.Euler(90,0,yaw);var canvas=new GameObject("Public face canvas",typeof(RectTransform),typeof(Canvas)).GetComponent<Canvas>();canvas.renderMode=RenderMode.WorldSpace;canvas.transform.SetParent(holder,false);canvas.transform.localScale=Vector3.one*.008f;canvas.GetComponent<RectTransform>().sizeDelta=new Vector2(110,150);var card=Card(name+" renderer",canvas.transform,new Vector2(110,150));return card;}
 static void BetUI(){var menu=m.menus;p.history=Text("Public action history",menu.pages[3].transform,"",new Vector2(460,530),new Vector2(565,-20),23);p.history.alignment=TextAlignmentOptions.TopLeft;menu.setupInfo.rectTransform.anchoredPosition=new Vector2(0,-305);menu.setupInfo.rectTransform.sizeDelta=new Vector2(1300,52);var setup=menu.pages[0].transform;p.stackOption=SportsUIAuthoring.Button(setup,"STACK","pokerstack",new Vector2(-440,210),new Vector2(390,30)).normalTextObj;p.blindOption=SportsUIAuthoring.Button(setup,"BLINDS","pokerblind",new Vector2(0,210),new Vector2(390,30)).normalTextObj;p.levelOption=SportsUIAuthoring.Button(setup,"LEVEL","pokerlevel",new Vector2(440,210),new Vector2(390,30)).normalTextObj;foreach(var text in new[]{p.stackOption,p.blindOption,p.levelOption}){text.fontSizeMax=19;text.fontSizeMin=17;}
 var settings=menu.pages[5].transform;var info=settings.Find("Info");if(info!=null)info.gameObject.SetActive(false);p.lookOption=SportsUIAuthoring.Button(settings,"LOOK SPEED","pokerlook",new Vector2(350,-150),new Vector2(550,52)).normalTextObj;p.invertOption=SportsUIAuthoring.Button(settings,"INVERT LOOK","pokerinvert",new Vector2(350,-225),new Vector2(550,52)).normalTextObj;
 p.panes=new PokerPane[4];for(int view=0;view<4;view++){var pane=new PokerPane();var root=SportsUIAuthoring.Rect("Owned Poker pane "+view,menu.hud.transform,Vector2.zero,Vector2.zero).GetComponent<RectTransform>();root.gameObject.AddComponent<RectMask2D>();pane.root=root;pane.own=new PokerCardView[2];pane.board=new PokerCardView[5];for(int c=0;c<5;c++){pane.board[c]=Card("Public board "+c,root,new Vector2(70,98));var r=pane.board[c].GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,0);r.anchoredPosition=new Vector2(55+c*78,210);}for(int c=0;c<2;c++){pane.own[c]=Card("Private held card "+c,root,new Vector2(70,98));var r=pane.own[c].GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(1,0);r.anchoredPosition=new Vector2(-50-c*78,210);pane.own[c].Clear(true);}pane.hint=Text("Private hand prompt",root,"HOLD TO PEEK",new Vector2(600,30),Vector2.zero,22);var hint=pane.hint.rectTransform;hint.anchorMin=new Vector2(0,0);hint.anchorMax=new Vector2(1,0);hint.pivot=new Vector2(.5f,0);hint.anchoredPosition=new Vector2(0,268);hint.sizeDelta=new Vector2(-30,30);
 var actions=SportsUIAuthoring.Rect("Owned betting controls",root,new Vector2(900,140),Vector2.zero);var ar=actions.GetComponent<RectTransform>();ar.anchorMin=new Vector2(0,0);ar.anchorMax=new Vector2(1,0);ar.pivot=new Vector2(.5f,0);ar.anchoredPosition=new Vector2(0,8);ar.sizeDelta=new Vector2(-24,140);actions.AddComponent<Image>().color=SportsBroadcastCanvas.Ink;actions.AddComponent<SportsBroadcastPlate>();pane.actions=actions;pane.bet=Text("Selected legal action",actions.transform,"",new Vector2(870,25),new Vector2(0,50),23);pane.reason=Text("Raise reason",actions.transform,"",new Vector2(870,24),new Vector2(0,-53),20);string[] labels={"FOLD","CHECK / CALL","RAISE","MIN","HALF POT","POT","ALL IN"};pane.choices=new Image[3];for(int action=0;action<7;action++){var button=SportsUIAuthoring.Button(actions.transform,labels[action],"ownedpoker",new Vector2(-390+action*130,12),new Vector2(120,34));UnityEngine.Object.DestroyImmediate(button.GetComponent<SportsMenuAction>());button.normalTextObj.fontSizeMax=18;button.normalTextObj.fontSizeMin=16;var route=button.gameObject.AddComponent<PokerMouseButton>();route.match=m;route.view=view;route.action=action;if(action<3)pane.choices[action]=button.GetComponent<Image>();}
 var slider=SportsUIAuthoring.Rect("Legal total slider",actions.transform,new Vector2(660,18),new Vector2(0,-26));var track=SportsUIAuthoring.Rect("Track",slider.transform,new Vector2(660,5),Vector2.zero);track.AddComponent<Image>().color=new Color(.22f,.27f,.35f);var handle=SportsUIAuthoring.Rect("Handle",slider.transform,new Vector2(16,18),Vector2.zero);handle.AddComponent<Image>().color=SportsBroadcastCanvas.Orange;pane.amount=slider.AddComponent<Slider>();pane.amount.wholeNumbers=true;pane.amount.handleRect=handle.GetComponent<RectTransform>();pane.amount.targetGraphic=handle.GetComponent<Image>();pane.amount.minValue=20;pane.amount.maxValue=1000;var amount=slider.AddComponent<PokerMouseAmount>();amount.match=m;amount.view=view;p.panes[view]=pane;}
 var spectator=SportsUIAuthoring.Rect("Public spectator board",menu.hud.transform,new Vector2(560,150),Vector2.zero);var sr=spectator.GetComponent<RectTransform>();sr.anchorMin=sr.anchorMax=new Vector2(.5f,0);sr.pivot=new Vector2(.5f,0);sr.anchoredPosition=new Vector2(0,90);p.spectatorRoot=spectator;p.spectatorBoard=new PokerCardView[5];for(int c=0;c<5;c++){p.spectatorBoard[c]=Card("Public spectator card "+c,spectator.transform,new Vector2(94,132));p.spectatorBoard[c].GetComponent<RectTransform>().anchoredPosition=new Vector2((c-2)*106,0);}p.Options();}
 static void Layer(Transform root,int layer){root.gameObject.layer=layer;foreach(Transform child in root)Layer(child,layer);}
 public static void Validate(){var match=UnityEngine.Object.FindAnyObjectByType<PokerMatch>();if(match==null){EditorSceneManager.OpenScene(Scene);match=UnityEngine.Object.FindAnyObjectByType<PokerMatch>();}if(match==null||match.presentation==null||match.avatars.Length!=8||match.seats.Length!=4||match.looks.Length!=4||match.presentation.seatCards.Length!=16||match.presentation.panes.Length!=4)throw new Exception("Poker scene references incomplete");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One poker listener required");foreach(var pane in match.presentation.panes)if(pane.own.Length!=2||pane.board.Length!=5||pane.amount==null||pane.root.GetComponent<RectMask2D>()==null)throw new Exception("Private pane boundaries incomplete");foreach(var root in EditorSceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing poker script "+t.name);PokerFixtures.Run();Debug.Log("POKER_NATIVE_SCENE_VALIDATED rules/private pane bounds/one listener");}
